import { useState, useMemo, useEffect } from 'react';
import { loadBulkIds, saveBulkIds, loadOrders, saveOrders, clearAllData } from './storage';

const TABS = ['Dashboard', 'Stock Manager', 'New Order', 'Order History'];

const fmtNum = (n) => Number(n).toLocaleString();
const fmtMoney = (n) => `$${Number(n).toFixed(2)}`;

const stockColor = (used, total) => {
  const pct = used / total;
  if (pct >= 0.9) return '#ff4d4d';
  if (pct >= 0.6) return '#ffaa00';
  return '#00e5a0';
};

export default function App() {
  const [bulkIds, setBulkIdsState] = useState([]);
  const [orders, setOrdersState] = useState([]);
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [orderForm, setOrderForm] = useState({ customerGameId: '', quantity: '' });
  const [orderResult, setOrderResult] = useState(null);
  const [notification, setNotification] = useState(null);
  const [newBulk, setNewBulk] = useState({ id: '', label: '', totalStock: '', pricePerUnit: '' });
  const [showAddBulk, setShowAddBulk] = useState(false);
  const [editBulk, setEditBulk] = useState(null);
  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Load from localStorage on startup
  useEffect(() => {
    setBulkIdsState(loadBulkIds());
    setOrdersState(loadOrders());
  }, []);

  // Save helpers that persist to localStorage
  const setBulkIds = (updater) => {
    setBulkIdsState((prev) => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      saveBulkIds(next);
      return next;
    });
  };

  const setOrders = (updater) => {
    setOrdersState((prev) => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      saveOrders(next);
      return next;
    });
  };

  const notify = (msg, type = 'success') => {
    setNotification({ msg, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const totalStats = useMemo(() => {
    const totalStock = bulkIds.reduce((a, b) => a + b.totalStock, 0);
    const usedStock = bulkIds.reduce((a, b) => a + b.usedStock, 0);
    const available = totalStock - usedStock;
    const totalEarnings = orders.reduce((a, o) => a + o.earnings, 0);
    return { totalStock, usedStock, available, totalEarnings };
  }, [bulkIds, orders]);

  const getBestBulkId = (qty) =>
    bulkIds
      .filter((b) => b.totalStock - b.usedStock >= qty)
      .sort((a, b) => b.totalStock - b.usedStock - (a.totalStock - a.usedStock))[0];

  const handlePlaceOrder = () => {
    const qty = parseInt(orderForm.quantity);
    if (!orderForm.customerGameId.trim() || !qty || qty <= 0) {
      notify('Please fill all fields correctly.', 'error');
      return;
    }
    const best = getBestBulkId(qty);
    if (!best) {
      notify('Insufficient stock across all Bulk IDs!', 'error');
      return;
    }
    const earnings = parseFloat((qty * best.pricePerUnit).toFixed(2));
    const newOrder = {
      id: `ORD-${String(orders.length + 1).padStart(4, '0')}`,
      customerGameId: orderForm.customerGameId,
      quantity: qty,
      bulkUsed: best.id,
      status: 'Fulfilled',
      date: new Date().toISOString().split('T')[0],
      time: new Date().toLocaleTimeString(),
      earnings,
    };
    setBulkIds((prev) =>
      prev.map((b) => (b.id === best.id ? { ...b, usedStock: b.usedStock + qty } : b))
    );
    setOrders((prev) => [newOrder, ...prev]);
    setOrderResult({ order: newOrder, bulk: best });
    setOrderForm({ customerGameId: '', quantity: '' });
    notify(`Order ${newOrder.id} fulfilled via ${best.id}!`);
  };

  const handleAddBulk = () => {
    if (!newBulk.id || !newBulk.label || !newBulk.totalStock || !newBulk.pricePerUnit) {
      notify('Fill all fields.', 'error');
      return;
    }
    if (bulkIds.find((b) => b.id === newBulk.id)) {
      notify('Bulk ID already exists.', 'error');
      return;
    }
    setBulkIds((prev) => [
      ...prev,
      {
        ...newBulk,
        totalStock: parseInt(newBulk.totalStock),
        usedStock: 0,
        pricePerUnit: parseFloat(newBulk.pricePerUnit),
      },
    ]);
    setNewBulk({ id: '', label: '', totalStock: '', pricePerUnit: '' });
    setShowAddBulk(false);
    notify('Bulk ID added and saved!');
  };

  const handleUpdateBulk = () => {
    setBulkIds((prev) =>
      prev.map((b) =>
        b.id === editBulk.id
          ? {
              ...b,
              label: editBulk.label,
              totalStock: parseInt(editBulk.totalStock),
              pricePerUnit: parseFloat(editBulk.pricePerUnit),
            }
          : b
      )
    );
    setEditBulk(null);
    notify('Bulk ID updated!');
  };

  const handleDeleteBulk = (id) => {
    if (window.confirm(`Delete ${id}? This cannot be undone.`)) {
      setBulkIds((prev) => prev.filter((b) => b.id !== id));
      notify(`${id} deleted.`);
    }
  };

  const handleClearAll = () => {
    clearAllData();
    setBulkIdsState([]);
    setOrdersState([]);
    setShowClearConfirm(false);
    notify('All data cleared.');
  };

  const filteredOrders = orders.filter(
    (o) =>
      o.customerGameId.toLowerCase().includes(searchQuery.toLowerCase()) ||
      o.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
      o.bulkUsed.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const exportCSV = () => {
    const headers = ['Order ID,Customer Game ID,Quantity,Bulk Used,Earnings,Date,Status'];
    const rows = orders.map(
      (o) => `${o.id},${o.customerGameId},${o.quantity},${o.bulkUsed},${o.earnings},${o.date},${o.status}`
    );
    const csv = [...headers, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `popstock_orders_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  return (
    <div style={styles.app}>
      <style>{css}</style>

      {notification && (
        <div className={`notif ${notification.type === 'success' ? 'ns' : 'ne'}`}>
          {notification.msg}
        </div>
      )}

      {/* HEADER */}
      <div style={styles.header}>
        <div>
          <div style={styles.logo}>
            <span style={{ color: '#5b6fff' }}>POP</span>STOCK
          </div>
          <div style={styles.logoSub}>Popularity Inventory Manager — Data saved locally on your PC</div>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <button className="btn-danger-sm" onClick={() => setShowClearConfirm(true)}>
            🗑 Clear All Data
          </button>
        </div>
      </div>

      {/* TABS */}
      <div style={styles.tabBar}>
        {TABS.map((t) => (
          <button
            key={t}
            className={`tab-btn ${activeTab === t ? 'active' : ''}`}
            onClick={() => { setActiveTab(t); setOrderResult(null); }}
          >
            {t}
          </button>
        ))}
      </div>

      {/* CLEAR CONFIRM MODAL */}
      {showClearConfirm && (
        <div style={styles.modal}>
          <div style={styles.modalBox}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#ff4d4d', marginBottom: 10 }}>⚠ Clear All Data?</div>
            <div style={{ color: '#9ba3cc', marginBottom: 20, fontSize: 14 }}>
              This will permanently delete all Bulk IDs, orders, and earnings from your PC storage.
            </div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button className="btn-danger" onClick={handleClearAll}>Yes, Delete Everything</button>
              <button className="btn-outline" onClick={() => setShowClearConfirm(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      <div style={styles.content}>

        {/* ── DASHBOARD ── */}
        {activeTab === 'Dashboard' && (
          <div>
            <div style={styles.statsGrid}>
              {[
                { label: 'TOTAL STOCK', value: fmtNum(totalStats.totalStock), icon: '📦', color: '#5b6fff' },
                { label: 'AVAILABLE', value: fmtNum(totalStats.available), icon: '✅', color: '#00e5a0' },
                { label: 'USED STOCK', value: fmtNum(totalStats.usedStock), icon: '📤', color: '#ffaa00' },
                { label: 'TOTAL EARNINGS', value: fmtMoney(totalStats.totalEarnings), icon: '💰', color: '#ff4d4d' },
              ].map((s) => (
                <div key={s.label} className="stat-card">
                  <div style={{ fontSize: 28, marginBottom: 8 }}>{s.icon}</div>
                  <div className="lbl">{s.label}</div>
                  <div style={{ fontSize: 28, fontWeight: 800, color: s.color, fontFamily: 'Space Mono, monospace' }}>
                    {s.value}
                  </div>
                </div>
              ))}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 20 }}>
              <div className="card">
                <div className="card-title">BULK ID STOCK STATUS</div>
                {bulkIds.length === 0 && (
                  <div style={{ color: '#4a5278', fontFamily: 'Space Mono, monospace', fontSize: 13 }}>
                    No Bulk IDs yet. Go to Stock Manager to add one.
                  </div>
                )}
                {bulkIds.map((b) => {
                  const avail = b.totalStock - b.usedStock;
                  const pct = b.totalStock > 0 ? b.usedStock / b.totalStock : 0;
                  const col = stockColor(b.usedStock, b.totalStock);
                  return (
                    <div key={b.id} style={{ marginBottom: 20 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
                        <div>
                          <span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{b.id}</span>
                          <span style={{ marginLeft: 10, color: '#6b7299', fontSize: 12 }}>{b.label}</span>
                        </div>
                        <div className="mono" style={{ fontSize: 12 }}>
                          <span style={{ color: col }}>{fmtNum(avail)}</span>
                          <span style={{ color: '#2a3050' }}> / {fmtNum(b.totalStock)}</span>
                        </div>
                      </div>
                      <div className="progress-bar">
                        <div style={{ height: '100%', width: `${pct * 100}%`, background: col, borderRadius: 3 }} />
                      </div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 4 }}>
                        <span className="mono" style={{ fontSize: 10, color: '#2a3050' }}>{(pct * 100).toFixed(1)}% used</span>
                        <span className="mono" style={{ fontSize: 10, color: '#2a3050' }}>${b.pricePerUnit}/unit</span>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="card">
                <div className="card-title">RECENT ORDERS</div>
                {orders.length === 0 && (
                  <div style={{ color: '#4a5278', fontFamily: 'Space Mono, monospace', fontSize: 13 }}>
                    No orders yet.
                  </div>
                )}
                {orders.slice(0, 6).map((o) => (
                  <div key={o.id} style={styles.recentOrderRow}>
                    <div>
                      <div className="mono" style={{ color: '#5b6fff', fontSize: 12, fontWeight: 700 }}>{o.id}</div>
                      <div style={{ fontSize: 12, color: '#6b7299', marginTop: 2 }}>{o.customerGameId}</div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <div className="mono" style={{ color: '#00e5a0', fontSize: 13 }}>{fmtMoney(o.earnings)}</div>
                      <div className="mono" style={{ fontSize: 11, color: '#2a3050' }}>{fmtNum(o.quantity)} units</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ── STOCK MANAGER ── */}
        {activeTab === 'Stock Manager' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <div className="page-title">MANAGE BULK IDS</div>
              <button className="btn-primary" onClick={() => setShowAddBulk(!showAddBulk)}>
                + Add New Bulk ID
              </button>
            </div>

            {showAddBulk && (
              <div className="card" style={{ marginBottom: 20 }}>
                <div className="card-title">NEW BULK ID</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr', gap: 14, marginBottom: 14 }}>
                  {[
                    { key: 'id', label: 'BULK ID', ph: 'e.g. BULK-003' },
                    { key: 'label', label: 'LABEL', ph: 'e.g. Pack Name' },
                    { key: 'totalStock', label: 'TOTAL STOCK', ph: 'e.g. 10000' },
                    { key: 'pricePerUnit', label: 'PRICE/UNIT ($)', ph: 'e.g. 0.05' },
                  ].map((f) => (
                    <div key={f.key}>
                      <div className="lbl">{f.label}</div>
                      <input
                        value={newBulk[f.key]}
                        onChange={(e) => setNewBulk((p) => ({ ...p, [f.key]: e.target.value }))}
                        placeholder={f.ph}
                      />
                    </div>
                  ))}
                </div>
                <div style={{ display: 'flex', gap: 10 }}>
                  <button className="btn-primary" onClick={handleAddBulk}>Save Bulk ID</button>
                  <button className="btn-outline" onClick={() => setShowAddBulk(false)}>Cancel</button>
                </div>
              </div>
            )}

            {/* Edit Modal */}
            {editBulk && (
              <div style={styles.modal}>
                <div style={styles.modalBox}>
                  <div className="card-title" style={{ marginBottom: 16 }}>EDIT {editBulk.id}</div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 16 }}>
                    {[
                      { key: 'label', label: 'LABEL' },
                      { key: 'totalStock', label: 'TOTAL STOCK' },
                      { key: 'pricePerUnit', label: 'PRICE/UNIT ($)' },
                    ].map((f) => (
                      <div key={f.key}>
                        <div className="lbl">{f.label}</div>
                        <input
                          value={editBulk[f.key]}
                          onChange={(e) => setEditBulk((p) => ({ ...p, [f.key]: e.target.value }))}
                        />
                      </div>
                    ))}
                  </div>
                  <div style={{ display: 'flex', gap: 10 }}>
                    <button className="btn-primary" onClick={handleUpdateBulk}>Update</button>
                    <button className="btn-outline" onClick={() => setEditBulk(null)}>Cancel</button>
                  </div>
                </div>
              </div>
            )}

            <div className="card">
              <table className="tbl">
                <thead>
                  <tr>
                    <th>BULK ID</th>
                    <th>LABEL</th>
                    <th>TOTAL STOCK</th>
                    <th>USED</th>
                    <th>AVAILABLE</th>
                    <th>PRICE/UNIT</th>
                    <th>STATUS</th>
                    <th>ACTIONS</th>
                  </tr>
                </thead>
                <tbody>
                  {bulkIds.length === 0 && (
                    <tr>
                      <td colSpan={8} style={{ color: '#4a5278', textAlign: 'center' }}>No Bulk IDs added yet.</td>
                    </tr>
                  )}
                  {bulkIds.map((b) => {
                    const avail = b.totalStock - b.usedStock;
                    const pct = b.totalStock > 0 ? b.usedStock / b.totalStock : 0;
                    const status = pct >= 0.9 ? 'LOW' : pct >= 0.6 ? 'MID' : 'OK';
                    const bc = pct >= 0.9 ? 'badge-red' : pct >= 0.6 ? 'badge-yellow' : 'badge-green';
                    const col = stockColor(b.usedStock, b.totalStock);
                    return (
                      <tr key={b.id}>
                        <td><span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{b.id}</span></td>
                        <td style={{ color: '#9ba3cc' }}>{b.label}</td>
                        <td className="mono">{fmtNum(b.totalStock)}</td>
                        <td className="mono" style={{ color: '#ffaa00' }}>{fmtNum(b.usedStock)}</td>
                        <td className="mono" style={{ color: col, fontWeight: 700 }}>{fmtNum(avail)}</td>
                        <td className="mono" style={{ color: '#00e5a0' }}>${b.pricePerUnit}</td>
                        <td><span className={`badge ${bc}`}>{status}</span></td>
                        <td>
                          <div style={{ display: 'flex', gap: 6 }}>
                            <button className="btn-sm" onClick={() => setEditBulk({ ...b })}>Edit</button>
                            <button className="btn-sm-danger" onClick={() => handleDeleteBulk(b.id)}>Del</button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ── NEW ORDER ── */}
        {activeTab === 'New Order' && (
          <div style={{ maxWidth: 600 }}>
            <div className="page-title" style={{ marginBottom: 20 }}>FULFILL CUSTOMER ORDER</div>
            <div className="card">
              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <div className="lbl">CUSTOMER IN-GAME ID</div>
                  <input
                    value={orderForm.customerGameId}
                    onChange={(e) => setOrderForm((p) => ({ ...p, customerGameId: e.target.value }))}
                    placeholder="e.g. Player#1234"
                  />
                </div>
                <div>
                  <div className="lbl">POPULARITY QUANTITY</div>
                  <input
                    type="number"
                    value={orderForm.quantity}
                    onChange={(e) => setOrderForm((p) => ({ ...p, quantity: e.target.value }))}
                    placeholder="e.g. 1000"
                  />
                </div>

                <div style={styles.previewBox}>
                  <div className="lbl" style={{ marginBottom: 8 }}>RECOMMENDED BULK ID TO USE</div>
                  {orderForm.quantity && parseInt(orderForm.quantity) > 0 ? (
                    (() => {
                      const best = getBestBulkId(parseInt(orderForm.quantity));
                      return best ? (
                        <div>
                          <span className="mono" style={{ color: '#5b6fff', fontWeight: 700, fontSize: 16 }}>{best.id}</span>
                          <span style={{ color: '#6b7299', marginLeft: 10, fontSize: 13 }}>{best.label}</span>
                          <div style={{ marginTop: 8, display: 'flex', gap: 20 }}>
                            <div>
                              <div className="lbl">AVAILABLE IN THIS ID</div>
                              <div className="mono" style={{ color: '#00e5a0', fontSize: 15 }}>{fmtNum(best.totalStock - best.usedStock)}</div>
                            </div>
                            <div>
                              <div className="lbl">ESTIMATED EARNINGS</div>
                              <div className="mono" style={{ color: '#ffaa00', fontSize: 15 }}>{fmtMoney(parseInt(orderForm.quantity) * best.pricePerUnit)}</div>
                            </div>
                            <div>
                              <div className="lbl">PRICE/UNIT</div>
                              <div className="mono" style={{ color: '#9ba3cc', fontSize: 15 }}>${best.pricePerUnit}</div>
                            </div>
                          </div>
                        </div>
                      ) : (
                        <span style={{ color: '#ff4d4d', fontSize: 13 }} className="mono">⚠ Not enough stock in any Bulk ID</span>
                      );
                    })()
                  ) : (
                    <span className="mono" style={{ color: '#2a3050', fontSize: 13 }}>Enter quantity above to see recommendation</span>
                  )}
                </div>

                <button className="btn-primary btn-full" onClick={handlePlaceOrder}>
                  ⚡ FULFILL ORDER
                </button>
              </div>
            </div>

            {orderResult && (
              <div className="card" style={{ borderColor: '#00e5a030', marginTop: 16 }}>
                <div className="mono" style={{ color: '#00e5a0', fontWeight: 700, fontSize: 14, marginBottom: 16 }}>
                  ✓ ORDER FULFILLED & SAVED
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
                  {[
                    { l: 'ORDER ID', v: orderResult.order.id },
                    { l: 'CUSTOMER', v: orderResult.order.customerGameId },
                    { l: 'BULK ID USED', v: orderResult.order.bulkUsed, color: '#5b6fff' },
                    { l: 'QUANTITY', v: fmtNum(orderResult.order.quantity) },
                    { l: 'EARNINGS', v: fmtMoney(orderResult.order.earnings), color: '#00e5a0' },
                    { l: 'DATE', v: orderResult.order.date },
                  ].map((f) => (
                    <div key={f.l}>
                      <div className="lbl">{f.l}</div>
                      <div className="mono" style={{ fontSize: 14, color: f.color || '#e8eaf0' }}>{f.v}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* ── ORDER HISTORY ── */}
        {activeTab === 'Order History' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <div className="page-title">{orders.length} TOTAL ORDERS</div>
              <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                <input
                  style={{ width: 220 }}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by ID, customer, bulk..."
                />
                <button className="btn-outline" onClick={exportCSV}>⬇ Export CSV</button>
              </div>
            </div>

            <div style={{ display: 'flex', gap: 16, marginBottom: 20 }}>
              {[
                { label: 'TOTAL ORDERS', value: orders.length, color: '#5b6fff' },
                { label: 'TOTAL EARNED', value: fmtMoney(totalStats.totalEarnings), color: '#00e5a0' },
                { label: 'TOTAL UNITS SOLD', value: fmtNum(orders.reduce((a, o) => a + o.quantity, 0)), color: '#ffaa00' },
              ].map((s) => (
                <div key={s.label} className="stat-card" style={{ flex: 1 }}>
                  <div className="lbl">{s.label}</div>
                  <div style={{ fontSize: 22, fontWeight: 800, color: s.color, fontFamily: 'Space Mono, monospace' }}>{s.value}</div>
                </div>
              ))}
            </div>

            <div className="card">
              <table className="tbl">
                <thead>
                  <tr>
                    <th>ORDER ID</th>
                    <th>CUSTOMER GAME ID</th>
                    <th>QUANTITY</th>
                    <th>BULK ID USED</th>
                    <th>EARNINGS</th>
                    <th>DATE</th>
                    <th>STATUS</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredOrders.length === 0 && (
                    <tr>
                      <td colSpan={7} style={{ color: '#4a5278', textAlign: 'center' }}>No orders found.</td>
                    </tr>
                  )}
                  {filteredOrders.map((o) => (
                    <tr key={o.id}>
                      <td><span className="mono" style={{ color: '#5b6fff', fontWeight: 700 }}>{o.id}</span></td>
                      <td style={{ color: '#9ba3cc' }}>{o.customerGameId}</td>
                      <td className="mono">{fmtNum(o.quantity)}</td>
                      <td><span className="mono" style={{ color: '#8b5cf6', fontWeight: 700 }}>{o.bulkUsed}</span></td>
                      <td><span className="mono" style={{ color: '#00e5a0' }}>{fmtMoney(o.earnings)}</span></td>
                      <td className="mono" style={{ color: '#4a5278' }}>{o.date}</td>
                      <td><span className="badge badge-green">{o.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

// ── STYLES ──
const styles = {
  app: { minHeight: '100vh', background: '#0a0c14', color: '#e8eaf0', fontFamily: "'Syne', 'Trebuchet MS', sans-serif" },
  header: { padding: '20px 32px', borderBottom: '1px solid #1a2040', display: 'flex', alignItems: 'center', justifyContent: 'space-between' },
  logo: { fontSize: 24, fontWeight: 800, color: '#fff', letterSpacing: '-0.02em' },
  logoSub: { fontSize: 11, color: '#4a5278', fontFamily: 'Space Mono, monospace', marginTop: 2 },
  tabBar: { padding: '0 32px', borderBottom: '1px solid #1a2040', display: 'flex', gap: 4 },
  content: { padding: '28px 32px', maxWidth: 1200, margin: '0 auto' },
  statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 24 },
  recentOrderRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14, paddingBottom: 14, borderBottom: '1px solid #1a2040' },
  previewBox: { background: '#0d1020', border: '1px solid #1a2040', borderRadius: 10, padding: 16 },
  modal: { position: 'fixed', inset: 0, background: '#000000aa', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 999 },
  modalBox: { background: '#111420', border: '1px solid #1a2040', borderRadius: 16, padding: 28, minWidth: 400 },
};

